						\tfrac{(1-\nu)(K+1)}{\alpha_{\rm max}}\min_{k\leq K}\|x_{k+1}-x_k\|^2
					\leq
						\sum_{k=0}^{K}\tfrac{1-\nu}{\alphk*}\|x_{k+1}-x_k\|^2
					\leq
						\bar{\originalvarphi}_0(x_{0}),
					\end{equation}
					where \cref{cond:alphk} was used to bound \(\alphk*\leq\alpha_{\rm max}\).

				\item \ref{thm:PG:boundedness}~
					We pattern the proof structure of \cite[Thm. 3.2]{solodov2007explicit}, thereby considering two mutually exclusive cases.
					\begin{proofitemize}[leftmargin=*,topsep=0pt]
					\item
						{\it Case 1: \(\cost_1(x_k)\geq\costinf*\) holds for \(k\) large enough.}

						Recall the definition of \(W_k\) and \(\mathcal L_k\) in \cref{thm:LW}.
						Observing that \(W_k\geq0\) and \(\frac12\|x_k-x_\star\|^2\leq\mathcal L_k(x_\star)\), \cref{thm:PG:qSD} implies that \(\seq{\mathcal L_k(x_\star)}\) converges and that consequently \(\seq{x_k}\) is bounded.

					\item
						{\it Case 2: \(\cost_1(x_k)<\costinf*\) holds infinitely often.}

						In this case, for every \(k\) large enough the index
						\begin{equation}\label{eq:ik}
							i_k
						\coloneqq
							\max\set{i\leq k}[\cost_1(x_i)<\costinf*]
						\end{equation}
						is well defined.
						We proceed by intermediate claims.
						\renewcommand{\claimscounter}{\ref*{thm:PG}}%
						\begin{claims}
						\item\label{claim:convergence:ik}%
							{\it the sequences \(\seq{x_{i_k}}\) and \(\seq{x_{i_k+1}}\) are bounded}.

							The optimal set
							\[
								\X_1
							=
								\set{x\in\X_2}[\cost_1(x)\leq \costinf*]
							=
								\set{x}[\cost_1(x)\leq\costinf*,\ \bcost_2(x)\leq0]
							\]
							coincides with a sublevel set of the convex function \(h\coloneqq\max\set{\cost_1-\costinf*,\bcost_2}\).
							Since it is nonempty and bounded by \cref{ass:X1}, \(h\) is level bounded; see, e.g., \cite[Prop. 11.13]{bauschke2017convex} or \cite[Lem. 1]{themelis2019acceleration}.
							Note that \cref{thm:PG:barPhi} implies that \(\seq{\bcost_2(x_k)}\) is (upper) bounded, which combined with the fact that \(\cost_1(x_{i_k})<\costinf*\) implies that \(\seq{x_{i_k}}\) lies in a sublevel set of \(h\), and is therefore bounded.
							In turn, \cref{thm:PG:barPhi} implies that so is \(\seq{x_{i_k+1}}\).
						\item
							{\it the whole sequence \(\seq{x_k}\) is bounded}.

							To this end, it remains to show that \(\seq{x_{k'}}[k'\in K']\) is bounded, where
							\begin{equation}\label{eq:K'}
								K'\coloneqq\set{k'\in\N}[k'\geq i_{k'}+2].
							\end{equation}
							With \(\rho_{\rm max}\) as in \cref{thm:PG:rhomax}, for every \(k\in\N\)
							\begin{align*}
								\mathcal L_{i_k+1}(x_\star)
							\leq{} &
								\overbracket[0.5pt]{
									\tfrac12
									\|x_{i_k+1}-x_\star\|^2
									\vphantom{\left(\tfrac{\sigma_{i_k+1}}{\sigma_{i_k}}\right)}
								}^{\text{bounded by \cref{claim:convergence:ik}}}
								+~~
								\overbracket*[0.5pt]{
									\tfrac{1}{4}\|x_{i_k+1}-x_{i_k}\|^2
									\vphantom{\left(\tfrac{\sigma_{i_k+1}}{\sigma_{i_k}}\right)}
								}^{\mathclap{\to0 \text{ by \cref{thm:PG:barPhi}}}}
								+
								\overbracket[0.5pt]{
									\sigma_{i_k+1}\alpha_{i_k+1}(1+\rho_{i_k+1})
									(\cost_1(x_{i_k})-\costinf*)
									\vphantom{\left(\tfrac{\sigma_{i_k+1}}{\sigma_{i_k}}\right)}
								}^{<0}
							\\
							&
								+
								\underbracket[0.5pt]{
									\alpha_{\rm max}\rho_{\rm max}^2
									\bcost_2(x_{i_k})
									+
									\alpha_{\rm max}\left(1-\tfrac{\sigma_{i_k+1}}{\sigma_{i_k}}\right)
									\bcost_2(x_{i_k+1})
								}_{\text{bounded by \cref{thm:PG:barPhi}}}.
							\end{align*}
							In particular, we have
							\begin{equation}\label{eq:supL}
								\sup_{k\in\N}\mathcal L_{i_k+1}(x_\star)<\infty.
							\end{equation}
							Let now \(k'\in K'\).
							Since \(\cost_1(x_j)-\costinf*\geq0\) for \(j=i_{k'}+1,\dots,k'\), observe that
							\begin{equation}\label{eq:Lk'geq}
								\tfrac12\|x_{k'}-x_\star\|^2
							\leq
								\mathcal L_{k'}(x_\star)
							\quad
								\forall k'\in K',
							\end{equation}
							and \cref{thm:PG:qSD} yields that
							\begin{align*}
								\mathcal L_{k'}(x_\star)
							\leq{} &
								\mathcal L_{k'-1}(x_\star)
							\leq\dots\leq
								\mathcal L_{i_{k'}+2}(x_\star)
							\numberthis\label{eq:Lk'descent}
							\\
							\leq{} &
								\mathcal L_{i_{k'}+1}(x_\star)
								-
								\sigma_{i_{k'}+1}\alpha_{i_{k'}+1}(1+\rho_{i_{k'}+1}-\rho_{i_{k'}+2}^2)
								\bigl(
									\cost_1(x_{i_{k'}})-\costinf*
								\bigr)
							\\
							\leq{} &
								\mathcal L_{i_{k'}+1}(x_\star)
								+
								\underbracket[0.5pt]{
									\tfrac{\sigma_{i_{k'}+1}}{\sigma_{i_{k'}}}
								}_{\leq1}
								\underbracket[0.5pt]{
									\vphantom{\tfrac{\sigma_{i_{k'}+1}}{\sigma_{i_{k'}}}}
									\alpha_{\rm max}(1+\rho_{i_{k'}+1}-\rho_{i_{k'}+2}^2)
								}_{\text{\clap{bounded by \cref{thm:PG:rhomax}}}}
								\underbracket[0.5pt]{
									\vphantom{\tfrac{\sigma_{i_{k'}+1}}{\sigma_{i_{k'}}}}
									\sigma_{i_{k'}}
									\bigl|
										\cost_1(x_{i_{k'}})-\costinf*
									\bigr|
								}_{\text{\clap{bounded by \cref{thm:PG:barPhi}}}}
								< \infty
							\qquad
								\forall k'\in K',
							\end{align*}
							where \eqref{eq:supL} was used in the last inequality.
							Here, boundedness of the under-bracketed term follows from boundedness of \(\seq{x_{i_{k'}}}[k'\in K']\) and lower semicontinuity of \(\cost_1\).
							Then, \eqref{eq:Lk'geq} implies that the sequence \(\seq{x_{k'}}[k'\in K']\) is bounded.
							Combined with \cref{claim:convergence:ik} and the fact that the index set \(K'\) is the complement of the indices therein, the claim follows.
						\qedhere
						\end{claims}
					\end{proofitemize}
				\end{proofitemize}
			\end{proof}

\begin{proof}
				We begin by remarking that boundedness of the sequence \(\seq{x_k}\) is ensured by \cref{cond:alphk,cond:alphk:nu}, as shown in \cref{thm:PG:boundedness}.
				We next prove each claim individually.
				\begin{proofitemize}
				\item \ref{thm:recipe:rate}~
					Consider a convergent subsequence \(x_{k_j}\to x_\infty\), so that \(x_{k_j+1}\to x_\infty\) by \cref{thm:PG:barPhi}.
					Up to further extracting if necessary we have that
					\(\alpha_{k_j+1}\to\alpha_\infty\geq\alpha_{\rm min}>0\) and \(\sigma_{k_j}\to0\).
					Observe that
					\begin{align*}
						x_{k+1}
					={} &
						\argmin h({}\cdot{};x_k,\alpha_{k+1},\sigk*),
					\shortintertext{where}
						h(w;x,\alpha,\sigma)
					\coloneqq{} &
						(\sigma \g_1+\g_2)(w)
						+
						\tfrac{1}{2\alpha}
						\bigl\|w-x+\alpha\nabla\bigl(\sigma \f_1+\f_2\bigr)(x)\bigr\|^2
					\end{align*}
					is level bounded in \(w\) locally uniformly in \((x,\alpha,\sigma)\), as a function from \(\R^n\times\bigl(\R^n\times[\alpha_{\rm min},\infty)\times[0,\infty)\bigr)\) to \(\Rinf\).
					Since \(h\) is continuous in \((x,\alpha,\sigma)\), it follows from \cite[Thm. 1.17]{rockafellar2011variational} that
					\[
						x_\infty
					\in
						\argmin h({}\cdot{};x_\infty,\alpha_\infty,0)
					=
						\prox_{\alpha_\infty \g_2}\bigl(x_\infty-\alpha_\infty\nabla \f_2(x_\infty)\bigr),
					\]
					this condition being equivalent to \(x_\infty\in\argmin(\f_2+\g_2)\defeq\X_2\).
					We next show that \(\bphik(x_k)\to0\).

					For any \(x_\star\in\X_1\), the subdifferential characterization of \(x_{k+1}\in\prox_{\alphk*\gk*}(x_k-\alphk*\nabla\fk*(x_k))\)
					\[
						\tfrac{x_{k-1}-x_k}{\alphk}
						-
						(\nabla\fk(x_{k-1})-\nabla\fk(x_k))
					\in
						\partial\phik(x_k)
					\]
					implies that
					\[
						\phik(x_\star)
					\geq
						\phik(x_k)
						+
						\innprod{
							\overbracket*[0.5pt]{
								\tfrac{x_{k-1}-x_k}{\alphk}
								-
								(\nabla\fk(x_{k-1})-\nabla\fk(x_k))
							}^{\to0 \text{ by \cref{thm:PG:barPhi}}}
						}{
							\overbracket*[0.5pt]{
								x_\star-x_k
								\vphantom{\tfrac{x_{k-1}-x_k}{\alphk}}
							}^{\text{\clap{bounded}}}
						},
					\]
					hence that
					\[
						\costinf_2
					=
						\lim_{k\to\infty}\phik(x_\star)
					\geq
						\limsup_{k\to\infty}\phik(x_k)
					=
						\limsup_{k\to\infty}\left(\sigk\bcost_1(x_k)+\overbracket*[0.5pt]{\cost_2(x_k)}^{\geq\costinf_2}\right)
					\geq
						\limsup_{k\to\infty}\sigk\bcost_1(x_k)
						+
						\costinf_2.
					\]
					Here, the second equality is obtained by adding and subtracting \(\sigk\costinf_1\) along with the fact that \(\sigk\to0\).
					Since \(\sigk\bcost_1\geq0\), necessarily \(\sigk\bcost_1(x_k)\to0\) and consequently \(\limsup_{k\to\infty}\cost_2(x_k)=\costinf_2\).
					Similarly, since \(\cost_2\geq\costinf_2\) this necessarily implies that \(\cost_2(x_k)\to\costinf_2\).
					This shows that \(\bcost_2(x^k)\to0\) as claimed.

					We next show that \(\seq{W_k}\) too is vanishing.
					Observe that
					\begin{align*}
						W_k
					\defeq{} &
						\tfrac{1-4\alphk\sigk\lk^{(2)}\Delk}{4}
						\overbracket[0.5pt]{
							\|x_k-x_{k-1}\|^2
						}^{\mathclap{\to 0\text{ by \cref{thm:PG:barPhi}}}}
						+
						\tfrac{\sigk*}{\sigk}\alphk*\rhok*
						\overbracket[0.5pt]{
							\bcost_2(x_{k-1})
						}^{\mathclap{\to 0}}
					\\
					&
						+
						\underbracket[0.5pt]{
							\sigk\alphk\Delk\bcost_2(x_k)
						}_{\to 0}
						+
						\alphk
						\left(1+\rhok\right)
						\underbracket[0.5pt]{
							\sigk
							\bigl(
								\cost_1(x_{k-1})
								-
								\costinf*
							\bigr)
						}_{\to0}
					\to
						0
					\quad\text{as \(k\to\infty\)},
					\end{align*}
					where we also used the fact that \(\seq{\alphk}\leq\alpha_{\rm max}\) and \(\seq{\rhok}\leq\rho_{\rm max}\) as in \cref{thm:PG:rhomax}.

					The asserted sublinear rate is a consequence of \eqref{eq:sublin:res}, the characterization of the residual in \cref{thm:H} (see \eqref{eq:Hk:phi}), and the upper bounds for \(\lk\), \(\Lk\) in \cref{thm:l<=L}:
					\begin{align*}
						\textstyle\sum_{k=0}^K\dist^2(0, \partial \phik*(x_{k+1})
					\leq{}&
						\textstyle\sum_{k=0}^K\tfrac{1}{\alphk*^2}\|\Hk*(x_{k})-\Hk*(x_{k+1}) \|^2
					\\
					\leq {}&
						\tfrac{M_{\rm max}^2}{\alpha_{\rm min}}\textstyle\sum_{k=0}^K \tfrac{1}{\alphk*}\|x_{k}-x_{k+1}\|^2
					\leq
						\tfrac{M_{\rm max}^2}{\alpha_{\rm min}(1-\nu)}\bar{\originalvarphi}_0(x_{0}),
					\end{align*}
					where \(M_{\rm max} = \sup_{k\in\N}M_k\leq 1+ \alpha_{\rm max}L_{f_0, \V}\), see \cref{thm:lL}.


				\item \ref{thm:recipe:solution}~
					We begin by observing that, since \(\bcost_2(x^k)\to0\), by lower semicontinuity all limit points of \(\seq{x^k}\) belong to \(\X_2\).
					As done in the proof of \cref{thm:PG:boundedness} we consider two possible cases.
					\begin{proofitemize}[leftmargin=*,topsep=0pt]
					\item
						{\it Case 1: \(\cost_1(x_k)\geq\costinf*\) holds for \(k\) large enough.}

						In this case, we will actually show that the sequence \(\seq{x_k}\) converges to a solution of \eqref{eq:P}.
						We first argue that there exists an optimal limit point; to this end, since all limit points are feasible and because of lower semicontinuity, it suffices to show that \(\liminf_{k\to\infty}\cost_1(x_k)=\costinf*\).
						A telescoping argument on \cref{thm:PG:qSD} along with \cref{cond:alphamin} yields
						\begin{equation}
							\alpha_{\rm min}\sum_{k\in \N}\sigk(1+\rhok-\rhok*^2)\bigl(\cost_1(x_{k-1})-\costinf*\bigr)
						\leq
							\sum_{k\in \N}\sigk\alphk(1+\rhok-\rhok*^2)\bigl(\cost_1(x_{k-1})-\costinf*\bigr)
						<
							\infty.
						\end{equation}
						Since \(\sum_{k\in\N}\sigk=\infty\), necessarily
						\begin{align*}
							\liminf_{k\to\infty}(1+\rhok-\rhok*^2)(\cost_1(x_{k-1})-\costinf*)
						=
							0.
							\numberthis\label{eq:liminf:cost1}
						\end{align*}
			% 			Observe first that
			% 			\begin{align*}
			% 				\rhok*
			% 			=
			% 				\tfrac{\sigk*\alphk*}{\sigk\alphk}
			% 			\leq
			% 				\tfrac{\sigk*\balphk*}{\sigk\alphk}
			% 			\leq
			% 				\tfrac{\sigk*}{\sigk}
			% 				\sqrt{\tfrac{\sigk}{\sigma_{k-1}}\bigl(1+\rhok\bigr)}
			% 				\tfrac{\sigk}{\sigk*}
			% 			\leq
			% 				\sqrt{1+\rhok}
			% 			,
			% 			\numberthis\label{eq:rhok:plus}
			% 			\end{align*}
			% 			where the first inequality holds by \cref{cond:alphk}, the second is due to the first term in \eqref{eq:adabim:alphk*_0}, and the last inequality follows from \eqref{eq:sigk}.
						Notice that \(\limsup_{k\to\infty}(1+\rhok-\rhok*^2)>0\), for otherwise \(1+\rhok-\rhok*^2 \to 0\), implying that \(\liminf_{k \to \infty} \rhok >0\), and consequently that \(\alphk\sigk\) eventually increases exponentially, which contradicts \(\sigk\alphk \leq \sigk\alpha_{\rm max} \to 0\).
						Hence, \(\limsup_{k\to\infty}(1+\rhok-\rhok*^2)>0\), which along with \eqref{eq:liminf:cost1} implies that \(\liminf_{k\to\infty}\cost_1(x_{k-1})=\costinf*\).
						Therefore, an optimal limit point exists, be it \(x_\infty\).
						Since \(W_k\to0\) by assertion \ref{thm:recipe:rate} and since \(\mathcal L_k(x_\infty)\) converges, it follows that \(\frac12\|x_k-x_\infty\|^2 = \mathcal L_k(x_\infty) - W_k\) converges as well.
						Since along a subsequence \(\frac12\|x_k-x_\infty\|^2\) converges to zero, necessarily \(\lim_{k\to\infty}\frac12\|x_k-x_\infty\|^2=0\), proving that the entire sequence \(\seq{x_k}\) converges to \(x_\infty\).
					\item
						{\it Case 2: \(\cost_1(x_k)<\costinf*\) holds infinitely often.}

						Recall the index \(i_k\) and the set \(K'\) defined in \eqref{eq:ik} and \eqref{eq:K'}.
			% 			Once we establish that all the limit points of \(\seq{x_{i_k}}\) and \(\seq{x_{i_k+1}}\) are optimal, {\red it only remains to show that
			% 			\(
			% 				\dist(x_{k'},\X_1)
			% 			\to
			% 				0
			% 			\)
			% 			as \(K'\ni k'\to\infty\)\note{Why}}.
						Having established boundedness of the entire sequence, limit points of \(\seq{x_{i_k}}\) exist and, as shown above, belong to \(\X_2\).
						Moreover, it follows from \eqref{eq:ik} that \(\limsup_{k\to\infty}\cost_1(x_{i_k})\leq\costinf*\), and a lower semicontinuity argument then yields that all the limit points of \(\seq{x_{i_k}}\) attain the optimal cost and are therefore optimal.
						Since \(x_{i_k}-x_{i_k+1}\to0\) by \cref{thm:PG:barPhi}, the same is also true for \(\seq{x_{i_k+1}}\), and in particular
						\(\dist(x_{i_{k}+1},\X_1) \to 0\) as \(k \to \infty\).

						For each \(k\) let \(\bar x_k\coloneqq\proj_{\X_1}\!x_k\), which is well defined since \(\X_1\neq\emptyset\) is closed and convex.
						Recalling that \(\mathcal L_k(x_\star)=W_k + \tfrac12\|x_k-x_\star\|^2\), for \(k'\in K'\) we have
						\begin{align*}
							\tfrac12\dist(x_{k'},\X_1)^2
						\leq{} &
							\tfrac12\|x_{k'}-\bar x_{i_{k'}+1}\|^2
						={}
							\mathcal L_{k'}(\bar x_{i_{k'}+1})-W_{k'}
						\\
							\dueto{\scriptsize by \eqref{eq:Lk'descent}}
							\
						\leq{} &
							\mathcal L_{i_{k'}+2}(\bar x_{i_{k'}+1})
							-
							W_{k'}
						={}
							% \tfrac12\dist(x_{i_{k'}+2},\X_1)^2
							\tfrac12\|x_{i_{k'}+2} - \bar x_{i_{k'}+1}\|^2
							+
							W_{i_{k'}+2}
							-
							W_{k'}
						\\
						\leq{} &
							\tfrac12\big(\dist(x_{i_{k'}+1},\X_1) + \|x_{i_{k'}+1} - x_{i_{k'}+2}\|\big)^2
							+
							W_{i_{k'}+2}
							-
							W_{k'}
						\to
							0
						\end{align*}
						as \(K'\ni k'\to\infty\), where the limit follows from \cref{thm:PG:barPhi}, the vanishing of \(\seq{W_k}\) established in assertion \ref{thm:recipe:rate}, and the fact that \(i_k\to\infty\) as \(k\to\infty\).
						Since \(K'\cup\set{i_k,i_k+1}[k\in\N]=\N\), we conclude that all the limit points of \(\seq{x^k}\) are optimal.
					\qedhere
					\end{proofitemize}
				\end{proofitemize}
			\end{proof}

