				4\left(1-\frac{\sigk}{\sigma_{k-1}}\right)
				\alphk\lk^{(2)}
			}
		}{
			2\sqrt{[\alphk^2 \Lk^2 - \alphk\lk]_+}
		}
	}
\end{equation}

A key step in our convergence analysis based on adaptive stepsizes relies on  the introduction of the quantities in \eqref{eq:lL}.
We define the shorhand notation for the forward operator \(\Hk = \id - \alphk\nabla\fk\), and note that by optimality conditions of the prox-grad update \eqref{eq:PG}
\begin{equation}\label{eq:Hk:phi}
	\tfrac1{\alphk}(\Hk(x_{k-1})-\Hk(x_k)) \in \partial \phik(x_k).
\end{equation}

\begin{equation}\label{eq:uppercase}
	\Phik=\Fk+\Gk
\quad\text{with}\quad
	\Fk=\tfrac1{\sigk}\fk=\f_1+\tfrac1{\sigk}\f_2
\quad\text{and}\quad
	\Gk=\tfrac1{\sigk}\gk=\g_1+\tfrac1{\sigk}\g_2,
\end{equation}
noticing that \(\Phik=\cost_1+\frac{1}{\sigk}\cost_2=\frac{1}{\sigk}\phik\).
Doing so allows us to express the difference
\begin{equation}
	\Phik*-\Phik
{}={}
	\left(\tfrac1{\sigk*}-\tfrac1{\sigk}\right)\cost_2
\end{equation}
as a multiple of the lower-level cost \(\cost_2\), rather than of the upper-level cost \(\cost_1\).

There exist \(\alpha_{\rm max}\geq\alpha_{\rm min}>0\) and \(\nu\in(0,1)\) such that, for every \(k\in\N\),

\begin{minipage}[t]{0.57\linewidth}
	\vspace*{-.5\baselineskip}%
	\begin{alphaproperties}
	\item \label{cond:alphk}%
		\(\alphk*\leq\min\set{\balphk*,\alpha_{\rm max}}\) with \(\balphk*\) as in \eqref{eq:adabim:alphk*_0}%

	\item \label{cond:alphk:nu}%
		\(\alphk*\lk*\leq\nu\)

	\item \label{cond:alphamin}%
		\(\alphk*\geq\alpha_{\rm min}\)
	\end{alphaproperties}
\end{minipage}
\hfill\vline\hfill
\begin{minipage}[t]{0.35\linewidth}
	\vspace*{-.5\baselineskip}%
	\begin{sigmaproperties}
	\item \label{cond:monotone}%
		\(0<\sigk* \leq \sigk\)

	\item \label{cond:slowcontrol}%
		\(\sigk\to 0\) and \(\sum_{k\in\N}\sigk=\infty\)
	\end{sigmaproperties}

\begin{proof}
				We begin by remarking that boundedness of the sequence \(\seq{x_k}\) is ensured by \cref{cond:alphk,cond:alphk:nu}, as shown in \cref{thm:PG:boundedness}.
				We next prove each claim individually.
				\begin{proofitemize}
				\item \ref{thm:recipe:rate}~
					Consider a convergent subsequence \(x_{k_j}\to x_\infty\), so that \(x_{k_j+1}\to x_\infty\) by \cref{thm:PG:barPhi}.
					Up to further extracting if necessary we have that
					\(\alpha_{k_j+1}\to\alpha_\infty\geq\alpha_{\rm min}>0\) and \(\sigma_{k_j}\to0\).
					Observe that
					\begin{align*}
						x_{k+1}
					={} &
						\argmin h({}\cdot{};x_k,\alpha_{k+1},\sigk*),
					\shortintertext{where}
						h(w;x,\alpha,\sigma)
					\coloneqq{} &
						(\sigma \g_1+\g_2)(w)
						+
						\tfrac{1}{2\alpha}
						\bigl\|w-x+\alpha\nabla\bigl(\sigma \f_1+\f_2\bigr)(x)\bigr\|^2
					\end{align*}
					is level bounded in \(w\) locally uniformly in \((x,\alpha,\sigma)\), as a function from \(\R^n\times\bigl(\R^n\times[\alpha_{\rm min},\infty)\times[0,\infty)\bigr)\) to \(\Rinf\).
					Since \(h\) is continuous in \((x,\alpha,\sigma)\), it follows from \cite[Thm. 1.17]{rockafellar2011variational} that
					\[
						x_\infty
					\in
						\argmin h({}\cdot{};x_\infty,\alpha_\infty,0)
					=
						\prox_{\alpha_\infty \g_2}\bigl(x_\infty-\alpha_\infty\nabla \f_2(x_\infty)\bigr),
					\]
					this condition being equivalent to \(x_\infty\in\argmin(\f_2+\g_2)\defeq\X_2\).
					We next show that \(\bphik(x_k)\to0\).

					For any \(x_\star\in\X_1\), the subdifferential characterization of \(x_{k+1}\in\prox_{\alphk*\gk*}(x_k-\alphk*\nabla\fk*(x_k))\)
					\[
						\tfrac{x_{k-1}-x_k}{\alphk}
						-
						(\nabla\fk(x_{k-1})-\nabla\fk(x_k))
					\in
						\partial\phik(x_k)
					\]
					implies that
					\[
						\phik(x_\star)
					\geq
						\phik(x_k)
						+
						\innprod{
							\overbracket*[0.5pt]{
								\tfrac{x_{k-1}-x_k}{\alphk}
								-
								(\nabla\fk(x_{k-1})-\nabla\fk(x_k))
							}^{\to0 \text{ by \cref{thm:PG:barPhi}}}
						}{
							\overbracket*[0.5pt]{
								x_\star-x_k
								\vphantom{\tfrac{x_{k-1}-x_k}{\alphk}}
							}^{\text{\clap{bounded}}}
						},
					\]
					hence that
					\[
						\costinf_2
					=
						\lim_{k\to\infty}\phik(x_\star)
					\geq
						\limsup_{k\to\infty}\phik(x_k)
					=
						\limsup_{k\to\infty}\left(\sigk\bcost_1(x_k)+\overbracket*[0.5pt]{\cost_2(x_k)}^{\geq\costinf_2}\right)
					\geq
						\limsup_{k\to\infty}\sigk\bcost_1(x_k)
						+
						\costinf_2.
					\]
					Here, the second equality is obtained by adding and subtracting \(\sigk\costinf_1\) along with the fact that \(\sigk\to0\).
					Since \(\sigk\bcost_1\geq0\), necessarily \(\sigk\bcost_1(x_k)\to0\) and consequently \(\limsup_{k\to\infty}\cost_2(x_k)=\costinf_2\).
					Similarly, since \(\cost_2\geq\costinf_2\) this necessarily implies that \(\cost_2(x_k)\to\costinf_2\).
					This shows that \(\bcost_2(x^k)\to0\) as claimed.

					We next show that \(\seq{W_k}\) too is vanishing.
					Observe that
					\begin{align*}
						W_k
					\defeq{} &
						\tfrac{1-4\alphk\sigk\lk^{(2)}\Delk}{4}
						\overbracket[0.5pt]{
							\|x_k-x_{k-1}\|^2
						}^{\mathclap{\to 0\text{ by \cref{thm:PG:barPhi}}}}
						+
						\tfrac{\sigk*}{\sigk}\alphk*\rhok*
						\overbracket[0.5pt]{
							\bcost_2(x_{k-1})
						}^{\mathclap{\to 0}}
					\\
					&
						+
						\underbracket[0.5pt]{
							\sigk\alphk\Delk\bcost_2(x_k)
						}_{\to 0}
						+
						\alphk
						\left(1+\rhok\right)
						\underbracket[0.5pt]{
							\sigk
							\bigl(
								\cost_1(x_{k-1})
								-
								\costinf*
							\bigr)
						}_{\to0}
					\to
						0
					\quad\text{as \(k\to\infty\)},
					\end{align*}
					where we also used the fact that \(\seq{\alphk}\leq\alpha_{\rm max}\) and \(\seq{\rhok}\leq\rho_{\rm max}\) as in \cref{thm:PG:rhomax}.

					The asserted sublinear rate is a consequence of \eqref{eq:sublin:res}, the characterization of the residual in \cref{thm:H} (see \eqref{eq:Hk:phi}), and the upper bounds for \(\lk\), \(\Lk\) in \cref{thm:l<=L}:
					\begin{align*}
						\textstyle\sum_{k=0}^K\dist^2(0, \partial \phik*(x_{k+1})
					\leq{}&
						\textstyle\sum_{k=0}^K\tfrac{1}{\alphk*^2}\|\Hk*(x_{k})-\Hk*(x_{k+1}) \|^2
					\\
					\leq {}&
						\tfrac{M_{\rm max}^2}{\alpha_{\rm min}}\textstyle\sum_{k=0}^K \tfrac{1}{\alphk*}\|x_{k}-x_{k+1}\|^2
					\leq
						\tfrac{M_{\rm max}^2}{\alpha_{\rm min}(1-\nu)}\bar{\originalvarphi}_0(x_{0}),
					\end{align*}
					where \(M_{\rm max} = \sup_{k\in\N}M_k\leq 1+ \alpha_{\rm max}L_{f_0, \V}\), see \cref{thm:lL}.


				\item \ref{thm:recipe:solution}~
					We begin by observing that, since \(\bcost_2(x^k)\to0\), by lower semicontinuity all limit points of \(\seq{x^k}\) belong to \(\X_2\).
					As done in the proof of \cref{thm:PG:boundedness} we consider two possible cases.
					\begin{proofitemize}[leftmargin=*,topsep=0pt]
					\item
						{\it Case 1: \(\cost_1(x_k)\geq\costinf*\) holds for \(k\) large enough.}

						In this case, we will actually show that the sequence \(\seq{x_k}\) converges to a solution of \eqref{eq:P}.
						We first argue that there exists an optimal limit point; to this end, since all limit points are feasible and because of lower semicontinuity, it suffices to show that \(\liminf_{k\to\infty}\cost_1(x_k)=\costinf*\).
						A telescoping argument on \cref{thm:PG:qSD} along with \cref{cond:alphamin} yields
						\begin{equation}
							\alpha_{\rm min}\sum_{k\in \N}\sigk(1+\rhok-\rhok*^2)\bigl(\cost_1(x_{k-1})-\costinf*\bigr)
						\leq
							\sum_{k\in \N}\sigk\alphk(1+\rhok-\rhok*^2)\bigl(\cost_1(x_{k-1})-\costinf*\bigr)
						<
							\infty.
						\end{equation}
						Since \(\sum_{k\in\N}\sigk=\infty\), necessarily
						\begin{align*}
							\liminf_{k\to\infty}(1+\rhok-\rhok*^2)(\cost_1(x_{k-1})-\costinf*)
						=
							0.
							\numberthis\label{eq:liminf:cost1}
						\end{align*}
			% 			Observe first that
			% 			\begin{align*}
			% 				\rhok*
			% 			=
			% 				\tfrac{\sigk*\alphk*}{\sigk\alphk}
			% 			\leq
			% 				\tfrac{\sigk*\balphk*}{\sigk\alphk}
