							\|x_{k-1}-x_k\|^2
						\label{eq:phikdescent}
						\\
						={} &
							P_{k-1}%
							-
							P_k%
							+
							(\tfrac{1}{\sigk}-\tfrac{1}{\sigma_{k-1}})\bcost_2(x_{k-1})
							-
							\tfrac{1-\alphk\lk}{\sigk\alphk}\|x_{k-1}-x_k\|^2.
						\label{eq:ineqsubgrad}
						\end{align}
					\end{subequations}
					Again from \eqref{eq:subgrad}, this time with \(k\gets k+1\), we have
					\begin{subequations}\label{subeq:3ineq}
						{\mathtight[0.6]%
						\begin{align*}
							0
						\leq{} &
							\Gk*(x_\star)
							-
							\Gk*(x_{k+1})
							+
							\innprod{\nabla\Fk*(x_k)}{x_\star-x_{k+1}}
							-
							\tfrac{1}{\sigk*\alphk*}
							\innprod{x_k-x_{k+1}}{x_\star-x_{k+1}}
						\\
						={} &
							\Gk*(x_\star)
							-
							\Gk*(x_{k+1})
							+
							\innprod{\nabla\Fk*(x_k)}{x_\star-x_{k+1}}
							+
							\tfrac{1}{2\sigk*\alphk*}
							\|x_k-x_\star\|^2
							-
							\tfrac{1}{2\sigk*\alphk*}
							\|x_\star-x_{k+1}\|^2
						\\
						&
							-
							\tfrac{1}{2\sigk*\alphk*}
							\|x_k-x_{k+1}\|^2
						\\
						={} &
							\Gk*(x_\star)
							-
							\Gk*(x_{k+1})
							+
							\innprod{\nabla\Fk*(x_k)}{x_\star-x_k}
							+
							\innprod{\nabla\Fk*(x_k)}{x_k-x_{k+1}}
							+
							\tfrac{1}{2\sigk*\alphk*}
