						\\
						&
							-
							\tfrac{1}{2\sigk*\alphk*}
							\|x_\star-x_{k+1}\|^2
							-
							\tfrac{1}{2\sigk*\alphk*}
							\|x_k-x_{k+1}\|^2
						\\
						\leq{} &
							\Gk*(x_\star)
							-
							\Gk*(x_{k+1})
							+
							\fillwidthof[c]{
								\innprod{\nabla\Fk*(x_k)}{x_\star-x_k}
							}{
