						\numberthis\label{eq:ineqA}
						\end{align*}
						Next, we bound the term (B) by \(\epsk*\)-Young's inequality as
						\begin{align*}
							\text{(B)}
						\leq{} &
							\tfrac{\epsk*}{2\sigk\alphk}\|x_k-x_{k+1}\|^2
							+
							\tfrac{1}{2\epsk*\sigk\alphk}\|\Hk(x_{k-1})-\Hk(x_k)\|^2
