						\end{align*}
					\end{subequations}
					Combining the three inequalities \eqref{subeq:3ineq} yields
					{\mathtight[0.9]%
					\begin{align*}
						0
					\leq{} &
						\Phik*(x_\star)
						-
						\Gk*(x_{k+1})
						-
						\Fk*(x_k)
						+
						\Gk(x_{k+1})
						-
						\Gk(x_k)
