	\begin{align*}
		\mathcal L_{k+1}(x_\star) - \mathcal L_k(x_\star)
	\leq{} &
		-
		\sigk*\alphk*
		\left(
			\overbracket*[0.5pt]{
				\tfrac{\Delk}{\rhok*}
			}^{\geq0}
			+
			\tfrac{1}{\sigk}
			\bigl(
				\overbracket*[0.5pt]{
					1+\rhok*
					-
					\rho_{k+2}^2\tfrac{\sigk}{\sigk*}
				}^{\geq0}
			\bigr)
		\right)
		\bcost_2(x_k)
	\\
	&
		-
		\sigk\alphk
		\bigl(
			\overbracket[0.5pt]{
				1+\rhok-\rhok*^2
			}^{\geq0}
		\bigr)
		\bigl(\cost_1(x_{k-1})-\costinf*\bigr)
	\\
	&
		-
		\left(
			\underbracket*[0.5pt]{
				\tfrac{1}{4}
				+
				\rhok*^2(\alphk\lk-\alphk^2\Lk^2)
				-
				\alphk\sigk\lk^{(2)}\Delk
			}_{\geq0}
		\right)
		\|x_{k-1}-x_k\|^2.
		\vphantom{
			\underbracket[0.5pt]{
				\tfrac{1}{4}
			}_0
		}
	\end{align*}
	The claim then readily follows from the fact that \(\bcost_2\geq0\), cf. \cref{thm:bar>=0}.

The convergence rate result follows immediately by telescoping \eqref{eq:descent:bphik}
\begin{equation}\label{eq:sublin:res}
	\tfrac{(1-\nu)(K+1)}{\alpha_{\rm max}}\min_{k\leq K}\|x_{k+1}-x_k\|^2
\leq
	\sum_{k=0}^{K}\tfrac{1-\nu}{\alphk*}\|x_{k+1}-x_k\|^2
\leq
	\bar{\originalvarphi}_0(x_{0}),
\end{equation}
where \cref{cond:alphk} was used to bound \(\alphk*\leq\alpha_{\rm max}\).

\item
	{\it Case 2: \(\cost_1(x_k)<\costinf*\) holds infinitely often.}

	In this case, for every \(k\) large enough the index
	\begin{equation}\label{eq:ik}
		i_k
	\coloneqq
		\max\set{i\leq k}[\cost_1(x_i)<\costinf*]
	\end{equation}
	is well defined.
	We proceed by intermediate claims.
	\renewcommand{\claimscounter}{\ref*{thm:PG}}%
	\begin{claims}

\item
	{\it the whole sequence \(\seq{x_k}\) is bounded}.

	To this end, it remains to show that \(\seq{x_{k'}}[k'\in K']\) is bounded, where
	\begin{equation}\label{eq:K'}
		K'\coloneqq\set{k'\in\N}[k'\geq i_{k'}+2].
	\end{equation}
	With \(\rho_{\rm max}\) as in \cref{thm:PG:rhomax}, for every \(k\in\N\)
	\begin{align*}
		\mathcal L_{i_k+1}(x_\star)
	\leq{} &
		\overbracket[0.5pt]{
			\tfrac12
			\|x_{i_k+1}-x_\star\|^2
			\vphantom{\left(\tfrac{\sigma_{i_k+1}}{\sigma_{i_k}}\right)}
		}^{\text{bounded by \cref{claim:convergence:ik}}}
		+~~
		\overbracket*[0.5pt]{
			\tfrac{1}{4}\|x_{i_k+1}-x_{i_k}\|^2
			\vphantom{\left(\tfrac{\sigma_{i_k+1}}{\sigma_{i_k}}\right)}
		}^{\mathclap{\to0 \text{ by \cref{thm:PG:barPhi}}}}
		+
		\overbracket[0.5pt]{
			\sigma_{i_k+1}\alpha_{i_k+1}(1+\rho_{i_k+1})
			(\cost_1(x_{i_k})-\costinf*)
			\vphantom{\left(\tfrac{\sigma_{i_k+1}}{\sigma_{i_k}}\right)}
		}^{<0}
	\\
	&
		+
		\underbracket[0.5pt]{
			\alpha_{\rm max}\rho_{\rm max}^2
			\bcost_2(x_{i_k})
			+
			\alpha_{\rm max}\left(1-\tfrac{\sigma_{i_k+1}}{\sigma_{i_k}}\right)
			\bcost_2(x_{i_k+1})
		}_{\text{bounded by \cref{thm:PG:barPhi}}}.
	\end{align*}
	In particular, we have
	\begin{equation}\label{eq:supL}
		\sup_{k\in\N}\mathcal L_{i_k+1}(x_\star)<\infty.
	\end{equation}

			Let now \(k'\in K'\).
			Since \(\cost_1(x_j)-\costinf*\geq0\) for \(j=i_{k'}+1,\dots,k'\), observe that
			\begin{equation}\label{eq:Lk'geq}
				\tfrac12\|x_{k'}-x_\star\|^2
			\leq
				\mathcal L_{k'}(x_\star)
			\quad
				\forall k'\in K',
			\end{equation}
			and \cref{thm:PG:qSD} yields that
			\begin{align*}
				\mathcal L_{k'}(x_\star)
			\leq{} &
				\mathcal L_{k'-1}(x_\star)
			\leq\dots\leq
				\mathcal L_{i_{k'}+2}(x_\star)
			\numberthis\label{eq:Lk'descent}
			\\
			\leq{} &
				\mathcal L_{i_{k'}+1}(x_\star)
				-
				\sigma_{i_{k'}+1}\alpha_{i_{k'}+1}(1+\rho_{i_{k'}+1}-\rho_{i_{k'}+2}^2)
				\bigl(
					\cost_1(x_{i_{k'}})-\costinf*
				\bigr)
			\\
			\leq{} &
				\mathcal L_{i_{k'}+1}(x_\star)
				+
				\underbracket[0.5pt]{
					\tfrac{\sigma_{i_{k'}+1}}{\sigma_{i_{k'}}}
				}_{\leq1}
				\underbracket[0.5pt]{
					\vphantom{\tfrac{\sigma_{i_{k'}+1}}{\sigma_{i_{k'}}}}
					\alpha_{\rm max}(1+\rho_{i_{k'}+1}-\rho_{i_{k'}+2}^2)
				}_{\text{\clap{bounded by \cref{thm:PG:rhomax}}}}
				\underbracket[0.5pt]{
					\vphantom{\tfrac{\sigma_{i_{k'}+1}}{\sigma_{i_{k'}}}}
					\sigma_{i_{k'}}
					\bigl|
						\cost_1(x_{i_{k'}})-\costinf*
					\bigr|
				}_{\text{\clap{bounded by \cref{thm:PG:barPhi}}}}
				< \infty
			\qquad
				\forall k'\in K',
			\end{align*}
			where \eqref{eq:supL} was used in the last inequality.
			Here, boundedness of the under-bracketed term follows from boundedness of \(\seq{x_{i_{k'}}}[k'\in K']\) and lower semicontinuity of \(\cost_1\).
			Then, \eqref{eq:Lk'geq} implies that the sequence \(\seq{x_{k'}}[k'\in K']\) is bounded.
			Combined with \cref{claim:convergence:ik} and the fact that the index set \(K'\) is the complement of the indices therein, the claim follows.
		\qedhere
		\end{claims}
	\end{proofitemize}
\end{proofitemize}

We begin by remarking that boundedness of the sequence \(\seq{x_k}\) is ensured by \cref{cond:alphk,cond:alphk:nu}, as shown in \cref{thm:PG:boundedness}.
We next prove each claim individually.
\begin{proofitemize}

We next show that \(\seq{W_k}\) too is vanishing.
Observe that
\begin{align*}
	W_k
\defeq{} &
	\tfrac{1-4\alphk\sigk\lk^{(2)}\Delk}{4}
	\overbracket[0.5pt]{
		\|x_k-x_{k-1}\|^2
	}^{\mathclap{\to 0\text{ by \cref{thm:PG:barPhi}}}}
	+
	\tfrac{\sigk*}{\sigk}\alphk*\rhok*
	\overbracket[0.5pt]{
		\bcost_2(x_{k-1})
	}^{\mathclap{\to 0}}
\\
&
	+
	\underbracket[0.5pt]{
		\sigk\alphk\Delk\bcost_2(x_k)
	}_{\to 0}
	+
	\alphk
	\left(1+\rhok\right)
	\underbracket[0.5pt]{
		\sigk
		\bigl(
			\cost_1(x_{k-1})
			-
			\costinf*
		\bigr)
	}_{\to0}
\to
	0
\quad\text{as \(k\to\infty\)},
\end{align*}
where we also used the fact that \(\seq{\alphk}\leq\alpha_{\rm max}\) and \(\seq{\rhok}\leq\rho_{\rm max}\) as in \cref{thm:PG:rhomax}.

		\item
			{\it Case 1: \(\cost_1(x_k)\geq\costinf*\) holds for \(k\) large enough.}

			In this case, we will actually show that the sequence \(\seq{x_k}\) converges to a solution of \eqref{eq:P}.
			We first argue that there exists an optimal limit point; to this end, since all limit points are feasible and because of lower semicontinuity, it suffices to show that \(\liminf_{k\to\infty}\cost_1(x_k)=\costinf*\).
